steps.script:
var cc = tree.current_scene.get_node_or_null("CommandController")
if cc == null:
	return "NO_CONTROLLER"
cc._refresh_ui()
return true

# The camera must have moved onto the unit under test...
var m = SceneRefs.main()
var moved = m.view_offset != m.get_meta("bs_test_offset")
# ...and every ALIVE model of it must be ringed on the board: 8 surviving
# Boyz plus the attached Warboss, which tests as part of the unit. Rings are
# named per model, so a rename collision cannot hide any of them.
var rings = 0
for c in SceneRefs.token_layer().get_children():
	if String(c.name).begins_with("BattleShockFocusRing_"):
		rings += 1
return [moved, rings == 9]

# The dice have settled on the real values and a verdict is on screen.
var d = tree.root.get_node("BattleShockSequenceDialog")
var total = d.get_node("Content/DiceRow/TotalLabel").text
var verdict = d.get_node("Content/VerdictLabel").get_parsed_text()
var tested = "U_BOYZ_E" in PhaseManager.get_current_phase_instance()._units_tested
var decided = verdict.contains("PASSED") or verdict.contains("FAILED")
return [total.begins_with("= "), decided, tested]

# The Kommandos must be framed in the band of screen that is actually board —
# above the docked roll-call card, below the top HUD bar, clear of the log and
# roster panels. Centring them (the old focus behaviour) would put them behind
# the card we just told the player to read.
var m = SceneRefs.main()
var cc = tree.current_scene.get_node_or_null("CommandController")
var centre: Vector2 = cc._bs_unit_centroid("U_KOMMANDOS_H")
var screen: Vector2 = (centre - m.view_offset) * m.view_zoom
var vp: Vector2 = m.get_viewport().get_visible_rect().size
var dlg = tree.root.get_node("BattleShockSequenceDialog")
return [screen.y > 108.0, screen.y < float(dlg.position.y), screen.x > 340.0, screen.x < vp.x - 400.0]

# Both units resolved, the focus rings are gone, and the summary names them.
var phase = PhaseManager.get_current_phase_instance()
var both = ("U_BOYZ_E" in phase._units_tested) and ("U_KOMMANDOS_H" in phase._units_tested)
var rings = 0
var layer = SceneRefs.token_layer()
if layer:
	for c in layer.get_children():
		if String(c.name).begins_with("BattleShockFocusRing_"):
			rings += 1
var summary = tree.root.get_node("BattleShockSequenceDialog/Content/VerdictLabel").get_parsed_text()
return [both, rings == 0, summary.contains("Boyz") and summary.contains("Kommandos")]

var m = SceneRefs.main()
var restored: Vector2 = m.view_offset
var original: Vector2 = m.get_meta("bs_test_offset")
return restored.distance_to(original) < 2.0

# Second segment: with CP in the bank, the roll call must offer INSANE
# BRAVERY on the card (it used to be a separate button in the side panel).
GameState.state["players"]["2"]["cp"] = 3
var phase = PhaseManager.get_current_phase_instance()
phase._units_tested.clear()
phase._units_auto_passed.clear()
phase._identify_units_needing_tests()
var cc = tree.current_scene.get_node_or_null("CommandController")
cc._refresh_ui()
return phase._units_needing_test.size()

var d = tree.root.get_node("BattleShockSequenceDialog")
var verdict = d.get_node("Content/VerdictLabel").get_parsed_text()
var cp_spent = int(GameState.state["players"]["2"]["cp"]) == 2
var shocked = GameState.state["units"]["U_BOYZ_E"].get("flags", {}).get("battle_shocked", false)
return [verdict.contains("AUTO-PASSED"), cp_spent, shocked]
